function retailerCard(p,key){ const isC=key==="coles", name=isC?"Coles":"Woolworths", current=p[key], typical=p[isC?"typicalColes":"typicalWoolworths"], special=p.special&&p.cheaper===name, diff=current-typical; const diffText=diff<0?`${money(Math.abs(diff))} below typical`:diff>0?`${money(diff)} above typical`:"Matches typical price"; return `<article class="retailer-price-card ${key}"><header><span class="retailer-badge">${isC?"C":"W"}</span><div><h3>${name}</h3><p>${special?"On Special":"Regular Price"}</p></div></header><strong class="current-price">${money(current)}</strong><dl><div><dt>Illustrative typical</dt><dd>${money(typical)}</dd></div><div><dt>Unit price</dt><dd>${unitPrice(p,key)}</dd></div><div><dt>Difference</dt><dd>${diffText}</dd></div></dl></article>`; }
function renderSummary(p){ $("#product-summary").innerHTML=`<div class="detail-image-wrap"><div class="detail-product-image product-image sprite-${p.image}" role="img" aria-label="Illustration of ${p.name} ${p.size}"></div>${p.special?'<span class="special-badge">On Special</span>':""}</div><div class="detail-identity"><p class="brand">${p.brand}</p><h1 id="detail-product-name">${p.name}</h1><p class="detail-size">${p.size}</p><div class="identity-tags"><span>${p.category}</span><span>${p.stability}</span></div></div><div class="detail-price-grid">${retailerCard(p,"coles")}${retailerCard(p,"woolworths")}</div><div class="required-date-card"><label for="required-date"><span>Required by</span><small>Your deadline shapes the recommendation.</small></label><input id="required-date" type="date" min="${dateValue(new Date())}" max="${dateValue(futureDate(30))}" value="${dateValue(futureDate(10))}" /></div>`; $("#required-date").onchange=()=>updateDecision(p); }

function historyData(p,weeks){ const missing=p.rec==="Insufficient Evidence"?Math.max(2,weeks-6):p.slug==="plain-flour"?Math.max(2,weeks-9):-1; return Array.from({length:weeks},(_,i)=>{ const date=futureDate(-(weeks-1-i)*7), wave=Math.sin((i+p.image)*1.32)*.055, dip=(i+p.image)%7===2?-.15:0; const c=i===weeks-1?p.coles:Math.max(.8,p.typicalColes*(1+wave+dip)); const w=i===weeks-1?p.woolworths:Math.max(.8,p.typicalWoolworths*(1-wave*.7+((i+3)%8===1?-.13:0))); return {date,coles:i===missing?null:+c.toFixed(2),woolworths:i===missing+1?null:+w.toFixed(2)}; }); }
function forecastData(p){ const wait=p.rec==="Wait", best=p.cheaper.toLowerCase(); return [7,14].map((days,i)=>{ const f=wait?(i? .86:.97):p.rec==="Buy Now"?1.02:.99; return {date:futureDate(days),coles:+(p.coles*(best==="coles"?f:1.01)).toFixed(2),woolworths:+(p.woolworths*(best==="woolworths"?f:1.01)).toFixed(2)}; }); }
function esc(v){return String(v).replace(/[<>&'"]/g,c=>({"<":"&lt;",">":"&gt;","&":"&amp;","'":"&apos;",'"':"&quot;"}[c]));}
function renderChart(p){
  const hist=historyData(p,selectedRange), fc=forecastData(p), all=[...hist,...fc], vals=all.flatMap(d=>[d.coles,d.woolworths]).filter(v=>v!==null), min=Math.floor((Math.min(...vals)-.25)*2)/2,max=Math.ceil((Math.max(...vals)+.25)*2)/2;
  const L=58,R=728,T=32,B=274, x=i=>L+(i/(all.length-1))*(R-L), y=v=>B-((v-min)/Math.max(.5,max-min))*(B-T), ci=hist.length-1;
  const segments=(data,key,off=0)=>{const out=[];let cur=[];data.forEach((d,i)=>{if(d[key]===null){if(cur.length)out.push(cur);cur=[];}else cur.push(`${x(i+off).toFixed(1)},${y(d[key]).toFixed(1)}`)});if(cur.length)out.push(cur);return out;};
  const grids=[0,.25,.5,.75,1].map(r=>{const v=max-r*(max-min),py=T+r*(B-T);return `<line class="grid-line" x1="${L}" y1="${py}" x2="${R}" y2="${py}"/><text class="axis-label" x="${L-10}" y="${py+4}" text-anchor="end">$${v.toFixed(2)}</text>`}).join("");
  const lines=["coles","woolworths"].flatMap(k=>segments(hist,k).map(points=>`<polyline class="series ${k}" points="${points.join(" ")}"/>`)).join("");
  const flines=["coles","woolworths"].map(k=>segments([{date:hist[ci].date,[k]:hist[ci][k]},...fc],k,ci).map(points=>`<polyline class="series ${k} forecast" points="${points.join(" ")}"/>`).join("")).join("");
  const dots=hist.flatMap((d,i)=>["coles","woolworths"].map(k=>{if(d[k]===null)return"";const retailer=k==="coles"?"Coles":"Woolworths",promo=d[k]<=p[k==="coles"?"typicalColes":"typicalWoolworths"]*.9,current=i===ci, tip=`${shortDate(d.date)}|${retailer}|${money(d[k])}${promo?"|Promotion event":""}`;return `<circle class="data-point ${k} ${current?"current":""} ${promo?"promotion":""}" cx="${x(i)}" cy="${y(d[k])}" r="${current?6:promo?4.5:3}" tabindex="0" data-tip="${esc(tip)}"><title>${esc(tip.replaceAll("|",", "))}</title></circle>`})).join("");
  const fdots=fc.flatMap((d,i)=>["coles","woolworths"].map(k=>{const retailer=k==="coles"?"Coles":"Woolworths",tip=`${shortDate(d.date)}|${retailer}|${money(d[k])}|Illustrative forecast`;return `<circle class="data-point ${k} forecast-point" cx="${x(ci+i+1)}" cy="${y(d[k])}" r="4" tabindex="0" data-tip="${esc(tip)}"><title>${esc(tip.replaceAll("|",", "))}</title></circle>`})).join("");
  const observed=hist.flatMap((d,i)=>["coles","woolworths"].map(k=>d[k]===null?null:{value:d[k],i,date:d.date})).filter(Boolean), low=observed.reduce((a,b)=>b.value<a.value?b:a), lx=x(low.i),ly=y(low.value), lowmark=`<path class="low-marker" d="M ${lx} ${ly-8} L ${lx+8} ${ly} L ${lx} ${ly+8} L ${lx-8} ${ly} Z" tabindex="0" data-tip="${esc(`${shortDate(low.date)}|Historical low|${money(low.value)}`)}"><title>Historical low, ${money(low.value)}</title></path>`;
  const step=Math.max(1,Math.floor((hist.length-1)/4)), labels=hist.map((d,i)=>i%step===0||i===ci?`<text class="axis-label" x="${x(i)}" y="302" text-anchor="middle">${shortDate(d.date)}</text>`:"").join("")+`<text class="axis-label forecast-date" x="${x(all.length-1)}" y="302" text-anchor="middle">${shortDate(fc[1].date)}</text>`, fstart=x(ci)+1;
  $("#price-chart").innerHTML=`<title id="chart-title">${p.name} illustrative price history and forecast</title><desc id="chart-desc">Solid observed demonstration lines for Coles and Woolworths, followed by a shaded illustrative forecast area with dashed lines.</desc><rect class="chart-bg" x="${L}" y="${T}" width="${R-L}" height="${B-T}" rx="12"/><rect class="forecast-zone" x="${fstart}" y="${T}" width="${R-fstart}" height="${B-T}"/>${grids}<line class="forecast-boundary" x1="${fstart}" y1="${T}" x2="${fstart}" y2="${B}"/><text class="forecast-zone-label" x="${fstart+10}" y="${T+18}">ILLUSTRATIVE FORECAST</text>${lines}${flines}${dots}${fdots}${lowmark}${labels}`;
  $("#missing-note").textContent=hist.some(d=>d.coles===null||d.woolworths===null)?"A visible line break marks dates without an illustrative observed price; missing dates are not interpolated.":"All weekly demonstration dates in this selected range include illustrative observed prices."; bindTips();
}
function bindTips(){const tip=$("#chart-tooltip"),wrap=$("#chart-wrap");const show=e=>{const p=e.currentTarget.dataset.tip.split("|");tip.innerHTML=`<strong>${p[1]}</strong><span>${p[0]} · ${p[2]}</span>${p[3]?`<em>${p[3]}</em>`:""}`;tip.hidden=false;const w=wrap.getBoundingClientRect(),r=e.currentTarget.getBoundingClientRect();tip.style.left=`${Math.min(w.width-155,Math.max(8,r.left-w.left-45))}px`;tip.style.top=`${Math.max(8,r.top-w.top-78)}px`;};const hide=e=>{if(e.type!=="blur"&&document.activeElement===e.currentTarget)return;tip.hidden=true;};$$('[data-tip]').forEach(n=>{n.onpointerenter=show;n.onpointerleave=hide;n.onfocus=show;n.onblur=hide;n.onclick=show;});}
function outlook(days,a){return `<article class="outlook-card"><header><span>Next ${days} days</span><strong class="likelihood ${a[0].toLowerCase()}">${a[0]} likelihood · ${a[1]}%</strong></header><p>${a[2]}</p><footer><span>Relevant retailer</span><b>${a[3]}</b></footer><small>Illustrative prototype output, not a validated probability.</small></article>`;}
