function reasonFor(p){if(p.rec==="Buy Now")return`Current ${p.cheaper} price is low against the illustrative history.`;if(p.rec==="Wait")return`A better illustrative promotion may occur within the forecast window.`;return`The demonstration history is not strong enough for a confident timing decision.`;}
function addBasket(p,fromWatch=false){
  if(state.basket.some(x=>x.productId===p.slug)){showToast(`${p.name} is already in your Basket.`);return;}
  const watched=state.watchlist.some(x=>x.productId===p.slug);
  if(watched&&!fromWatch&&!confirm(`${p.name} is already in your Watchlist. Move it to Basket instead?`))return;
  if(watched)state.watchlist=state.watchlist.filter(x=>x.productId!==p.slug);
  state.basket.push({productId:p.slug,quantity:1,retailer:p.cheaper.toLowerCase()});saveState();showToast(`${p.name} was added to Basket. ${p.cheaper} is selected by default.`);
}
function maybeReward(p,requiredBy){if(p.rec!=="Wait"||requiredBy<=dateValue(new Date())||state.assistant.rewarded.includes(p.slug))return false;state.assistant.rewarded.push(p.slug);state.assistant.coins+=10;state.assistant.mood="Proud";addMessage("maple","+10 coins — You chose to wait for a potentially better price.",false);return true;}
function openWatchDialog(p,requiredBy=dateValue(futureDate(10)),fromBasket=false){
  if(state.watchlist.some(x=>x.productId===p.slug)&&!fromBasket){showToast(`${p.name} is already in your Watchlist.`);return;}
  const inBasket=state.basket.some(x=>x.productId===p.slug);
  if(inBasket&&!fromBasket&&!confirm(`${p.name} is already in your Basket. Move it to Watchlist instead?`))return;
  pendingWatch={product:p,fromBasket:fromBasket||inBasket};const dialog=$("#watch-dialog");$("#watch-dialog-title").textContent=`Watch ${p.name}`;$("#watch-dialog-copy").textContent="Choose when you need it and add an optional price target.";$("#watch-required-date").min=dateValue(new Date());$("#watch-required-date").value=normalDate(requiredBy);$("#watch-target-price").value="";$("#watch-dialog-error").textContent="";dialog.showModal();
}
function emptyList(kind){const basket=kind==="basket";return `<div class="list-empty"> <img src="./assets/pricepaw-cat.png" alt="Maple, the PromoPaw shopping assistant"/><div><p class="eyebrow">Maple can help</p><h2>${basket?"Your Basket is empty":"Nothing is being watched yet"}</h2><p>${basket?"Browse the catalogue and add products when you’re ready to compare your shop.":"Watch products when you have time to wait for a worthwhile illustrative promotion."}</p><button type="button" data-go-shop>Browse products</button></div></div>`;}
function totals(){return state.basket.reduce((a,item)=>{const p=products.find(x=>x.slug===item.productId);if(!p)return a;const q=Math.max(1,Number(item.quantity)||1);a.coles+=(Number(p.coles)||0)*q;a.woolworths+=(Number(p.woolworths)||0)*q;a.split+=Math.min(Number(p.coles)||0,Number(p.woolworths)||0)*q;return a;},{coles:0,woolworths:0,split:0});}
function basketRow(item){const p=products.find(x=>x.slug===item.productId),selected=p[item.retailer],line=selected*item.quantity;return `<article class="basket-item" data-item="${p.slug}">${productThumb(p)}<div class="list-product-main"><p class="brand">${p.brand}</p><h2>${p.name} <span>${p.size}</span></h2><div class="mini-prices"><span><i class="mini-c">C</i> Coles <b>${money(p.coles)}</b></span><span><i class="mini-w">W</i> Woolworths <b>${money(p.woolworths)}</b></span></div><p class="item-reason"><strong>${p.rec}</strong> · ${reasonFor(p)}</p></div><div class="basket-controls"><label>Selected retailer<select data-retailer="${p.slug}"><option value="coles" ${item.retailer==="coles"?"selected":""}>Coles</option><option value="woolworths" ${item.retailer==="woolworths"?"selected":""}>Woolworths</option></select></label><div><span class="control-label">Quantity</span><div class="quantity-control"><button type="button" data-qty="-1" data-id="${p.slug}" aria-label="Decrease ${p.name} quantity">−</button><input value="${item.quantity}" inputmode="numeric" aria-label="${p.name} quantity" data-qty-input="${p.slug}"/><button type="button" data-qty="1" data-id="${p.slug}" aria-label="Increase ${p.name} quantity">+</button></div></div></div><div class="line-total"><span>Line total</span><strong>${money(line)}</strong><small>${p.cheaper} recommended</small></div><div class="item-actions"><button type="button" data-move-watch="${p.slug}">Move to Watchlist</button><button type="button" data-remove-basket="${p.slug}">Remove</button></div></article>`;}
function renderBasket(){const root=$("#basket-content");if(!state.basket.length){root.innerHTML=emptyList("basket");bindGoShop();return;}const t=totals(),cheapest=Math.min(t.coles,t.woolworths),saving=cheapest-t.split;root.innerHTML=`<div class="prototype-list-note">Prices, promotion outlooks and recommendations in this prototype are illustrative and are not live retailer observations.</div><div class="basket-layout"><div class="list-items">${state.basket.map(basketRow).join("")}</div><aside class="basket-summary"><p class="eyebrow">Basket comparison</p><h2>Compare your total</h2><div class="summary-option"><span><i class="mini-c">C</i> All items at Coles</span><strong>${money(t.coles)}</strong></div><div class="summary-option"><span><i class="mini-w">W</i> All items at Woolworths</span><strong>${money(t.woolworths)}</strong></div><div class="summary-option best-summary"><span>Split basket · lowest price</span><strong>${money(t.split)}</strong></div><div class="saving-callout"><span>Grocery saving</span><strong>${money(saving)}</strong><small>Compared with the cheapest single-store basket.</small></div><p class="travel-note">Grocery comparison before additional travel costs.</p><button type="button" class="trip-future" id="trip-future">Compare stores &amp; plan my Clayton trip</button><small>Uses the same illustrative Basket prices and quantities.</small></aside></div>`;bindBasket();}
function bindBasket(){
  $$('[data-qty]').forEach(b=>b.onclick=()=>{const item=state.basket.find(x=>x.productId===b.dataset.id);item.quantity=Math.max(1,item.quantity+Number(b.dataset.qty));saveState();});
  $$('[data-qty-input]').forEach(input=>input.onchange=()=>{const item=state.basket.find(x=>x.productId===input.dataset.qtyInput);item.quantity=Math.max(1,Math.min(99,Math.floor(Number(input.value)||1)));saveState();});
  $$('[data-retailer]').forEach(select=>select.onchange=()=>{const item=state.basket.find(x=>x.productId===select.dataset.retailer);item.retailer=select.value;saveState();});
  $$('[data-remove-basket]').forEach(b=>b.onclick=()=>{state.basket=state.basket.filter(x=>x.productId!==b.dataset.removeBasket);saveState();showToast("Item removed from Basket.");});
  $$('[data-move-watch]').forEach(b=>{b.onclick=()=>openWatchDialog(products.find(x=>x.slug===b.dataset.moveWatch),dateValue(futureDate(10)),true);});
  $("#trip-future").onclick=()=>openTrip(true);
}
function watchStatus(p,item){const days=daysUntil(item.requiredBy),best=Math.min(p.coles,p.woolworths);if(p.rec==="Insufficient Evidence")return["?","Insufficient Evidence","The illustrative history is not strong enough for a confident timing decision."];if(days<=3)return["!","Buy Before Your Deadline",`Only ${days===0?"today":`${days} day${days===1?"":"s"}`} remain before you need it.`];if(item.targetPrice!==null&&best<=item.targetPrice)return["✓","Good Time to Buy",`The current best illustrative price has reached your target.`];if(p.rec==="Buy Now")return["✓","Good Time to Buy",`The current price is already low against the illustrative history.`];return["⌛","Keep Waiting",`There is still time before the required date and a promotion may occur.`];}
function watchRow(item){const p=products.find(x=>x.slug===item.productId),best=Math.min(p.coles,p.woolworths),retailer=p.coles<=p.woolworths?"Coles":"Woolworths",s=watchStatus(p,item);return `<article class="watch-item status-${s[1].toLowerCase().replaceAll(" ","-")}" data-item="${p.slug}">${productThumb(p)}<div class="list-product-main"><p class="brand">${p.brand}</p><h2>${p.name} <span>${p.size}</span></h2><p class="best-price">Best current illustrative price <strong>${money(best)} at ${retailer}</strong></p><p class="current-recommendation">PromoPaw recommendation: <strong>${p.rec}</strong></p><div class="watch-status"><i aria-hidden="true">${s[0]}</i><div><strong>${s[1]}</strong><span>${s[2]}</span></div></div><small class="status-disclosure">Prototype status derived from illustrative data, not live monitoring.</small></div><div class="watch-edit"><label>Required by<input type="date" min="${dateValue(new Date())}" value="${item.requiredBy}" data-watch-date="${p.slug}"/></label><label>Target price <span>(optional)</span><div class="money-input"><span>$</span><input type="number" min="0" step="0.01" value="${item.targetPrice??""}" placeholder="No target" data-watch-target="${p.slug}"/></div></label></div><div class="watch-outlooks"><div><span>Next 7 days</span><strong>${p.outlook7[0]} · ${p.outlook7[1]}%</strong></div><div><span>Next 14 days</span><strong>${p.outlook14[0]} · ${p.outlook14[1]}%</strong></div><small>Illustrative prototype outputs.</small></div><div class="item-actions"><button type="button" data-move-basket="${p.slug}">Move to Basket</button><button type="button" data-remove-watch="${p.slug}">Remove</button></div></article>`;}
function renderWatchlist(){const root=$("#watchlist-content");if(!state.watchlist.length){root.innerHTML=emptyList("watchlist");bindGoShop();return;}root.innerHTML=`<div class="prototype-list-note">Prices, promotion outlooks and recommendations in this prototype are illustrative and are not live retailer observations.</div><div class="list-items">${state.watchlist.map(watchRow).join("")}</div>`;bindWatchlist();}
function bindWatchlist(){
  $$('[data-watch-date]').forEach(input=>input.onchange=()=>{const item=state.watchlist.find(x=>x.productId===input.dataset.watchDate);item.requiredBy=normalDate(input.value);saveState();showToast("Required-by date updated.");});
  $$('[data-watch-target]').forEach(input=>input.onchange=()=>{const item=state.watchlist.find(x=>x.productId===input.dataset.watchTarget),n=input.value===""?null:Number(input.value);item.targetPrice=Number.isFinite(n)&&n>=0?n:null;saveState();showToast(n!==null&&n<0?"Target price cannot be below zero.":"Target price updated.");});
  $$('[data-remove-watch]').forEach(b=>b.onclick=()=>{state.watchlist=state.watchlist.filter(x=>x.productId!==b.dataset.removeWatch);saveState();showToast("Item removed from Watchlist.");});
  $$('[data-move-basket]').forEach(b=>b.onclick=()=>{const p=products.find(x=>x.slug===b.dataset.moveBasket);state.watchlist=state.watchlist.filter(x=>x.productId!==p.slug);addBasket(p,true);});
}
function bindGoShop(){$$('[data-go-shop]').forEach(b=>b.onclick=()=>showShop(true));}
function selectedBasketTotal(){return state.basket.reduce((sum,item)=>{const p=products.find(x=>x.slug===item.productId);if(!p)return sum;const retailer=["coles","woolworths"].includes(item.retailer)?item.retailer:p.cheaper.toLowerCase();return sum+(Number(p[retailer])||0)*Math.max(1,Number(item.quantity)||1);},0);}
function forecastForDate(value){const start=new Date();start.setHours(12,0,0,0);const selected=new Date(`${value}T12:00:00`),days=Math.round((selected-start)/86400000);if(days<0||days>7)return null;const range=({0:[1.78,1.86],1:[1.73,1.81],2:[1.69,1.77],3:[1.72,1.82],4:[1.77,1.87],5:[1.80,1.90],6:[1.80,1.88]})[selected.getDay()],mid=+(range.reduce((a,b)=>a+b,0)/2).toFixed(2);return{low:range[0],high:range[1],mid,level:mid<=1.75?"Relatively low":mid>=1.85?"Relatively high":"Typical",confidence:"Medium"};}
function fuelTimeline(){return Array.from({length:7},(_,i)=>{const d=futureDate(i+1);return{date:d,...forecastForDate(dateValue(d))};});}
function tripAnalysis(){const settings=state.trip||cleanTrip(),t=totals(),selected=selectedBasketTotal(),single=Math.min(t.coles,t.woolworths),singleRetailer=t.coles<=t.woolworths?"Coles":"Woolworths",grocerySaving=single-selected,storeCount=new Set(state.basket.filter(item=>validProduct(item.productId)).map(item=>["coles","woolworths"].includes(item.retailer)?item.retailer:products.find(p=>p.slug===item.productId).cheaper.toLowerCase())).size,extraDistance=storeCount>1?TRIP_DISTANCE.extra:0,tripDistance=storeCount>1?TRIP_DISTANCE.split:TRIP_DISTANCE.single,forecast=forecastForDate(settings.shoppingDate),fuelPrice=forecast?.mid||CURRENT_U91,efficiency=Number(settings.efficiency)>0?Number(settings.efficiency):7.5,refill=Math.max(0,Number(settings.refillLitres)||0),litres=extraDistance*efficiency/100,routeCost=litres*fuelPrice,fuelSaving=settings.needFuel&&forecast?Math.max(0,(CURRENT_U91-forecast.mid)*refill):0,useSplit=storeCount>1&&grocerySaving>routeCost&&grocerySaving>0,totalBenefit=grocerySaving+fuelSaving-routeCost;return{t,selected,single,singleRetailer,grocerySaving,storeCount,extraDistance,tripDistance,forecast,fuelPrice,litres,routeCost,fuelSaving,useSplit,totalBenefit};}
function scenarioProducts(key){return state.basket.map(item=>{const p=products.find(x=>x.slug===item.productId),store=key==="split"?(item.retailer==="coles"?"Coles":"Woolworths"):key==="coles"?"Coles":"Woolworths";return `${p.name} ${p.size} × ${item.quantity} → ${store}`;});}
function scenarioCard(kind,title,total,stops,route,difference,recommended){const icon=kind==="coles"?'<i class="mini-c">C</i>':kind==="woolworths"?'<i class="mini-w">W</i>':'<i class="mini-s">1·2</i>',comparison=Math.abs(difference)<.005?"Baseline · $0.00 difference":difference<0?`${money(Math.abs(difference))} more than baseline`:`Save ${money(difference)}`;return `<article class="trip-scenario ${recommended?"recommended":""}">${recommended?'<span class="recommended-ribbon">Recommended</span>':""}<header><span>${icon}</span><h3>${title}</h3><strong>${money(total)}</strong></header><ul>${scenarioProducts(kind).map(x=>`<li>${x}</li>`).join("")}</ul><dl><div><dt>Store stops</dt><dd>${stops}</dd></div><div><dt>Route assumption</dt><dd>${route}</dd></div><div><dt>Baseline comparison</dt><dd>${comparison}</dd></div></dl></article>`;}
function mapMarker(id,x,y,label){return `<g class="map-marker ${id}" tabindex="0" role="button" data-map-marker="${id}" aria-label="Show ${CLAYTON_LOCATIONS[id].name}"><circle cx="${x}" cy="${y}" r="18"/><text x="${x}" y="${y+5}" text-anchor="middle">${label}</text></g>`;}
function mapMarkup(a){const storeInfo=id=>{const items=state.basket.filter(x=>x.retailer===id),subtotal=items.reduce((s,x)=>s+products.find(p=>p.slug===x.productId)[id]*x.quantity,0);return `${items.length?items.map(x=>products.find(p=>p.slug===x.productId).name).join(", "):"No products currently assigned"} · ${money(subtotal)}`;};return `<section class="trip-card map-card"><div class="section-heading"><div><p class="eyebrow">Clayton prototype route map</p><h2>Explore the suggested stops</h2></div><span class="map-fallback-label">Offline visual · no live tiles</span></div><div class="prototype-map"><svg viewBox="0 0 720 390" role="img" aria-label="Schematic Clayton route: Start, then Coles, Woolworths and fuel stop"><defs><marker id="arrow-coles" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="#B73532"/></marker><marker id="arrow-wool" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="#2F7D3B"/></marker><marker id="arrow-fuel" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="#C8953D"/></marker></defs><rect class="map-ground" width="720" height="390" rx="20"/><path class="map-road major" d="M42 304 C180 250 250 272 356 213 S560 80 684 88"/><path class="map-road" d="M100 76 C210 128 320 100 430 158 S600 248 678 314"/><path class="map-road" d="M196 30 C218 110 250 180 278 350"/><text x="496" y="66">Dandenong Road</text><text x="66" y="287">Centre Road</text><text x="210" y="62">Clayton Road</text><path class="route coles-route" marker-end="url(#arrow-coles)" d="M367 179 C292 220 230 267 166 291"/><path class="route wool-route" marker-end="url(#arrow-wool)" d="M166 291 C258 340 414 282 492 184 S553 118 590 104"/><path class="route fuel-route" marker-end="url(#arrow-fuel)" d="M590 104 C610 155 616 215 602 268"/>${mapMarker("start",367,179,"S")}${mapMarker("coles",166,291,"1")}${mapMarker("woolworths",590,104,"2")}${mapMarker("fuel",602,268,"3")}</svg><div class="map-legend"><span><i class="start-key">S</i> Start</span><span><i class="coles-key">1</i> Coles · dashed</span><span><i class="wool-key">2</i> Woolworths · solid</span><span><i class="fuel-key">3</i> Fuel · dotted</span></div></div><p class="route-order-note"><strong>Route order:</strong> Start → 1 Coles Clayton → 2 Woolworths Clayton M-City → 3 EG Ampol Clayton → return journey</p><div class="marker-detail" id="marker-detail" aria-live="polite"><strong>Starting point — Clayton</strong><span>Neutral demonstration origin; no home address requested or stored.</span></div><div class="trip-stops"><button type="button" data-map-marker="coles"><b>1</b><span><strong>${CLAYTON_LOCATIONS.coles.name}</strong><small>${storeInfo("coles")}</small></span></button><button type="button" data-map-marker="woolworths"><b>2</b><span><strong>${CLAYTON_LOCATIONS.woolworths.name}</strong><small>${storeInfo("woolworths")}</small></span></button><button type="button" data-map-marker="fuel"><b>3</b><span><strong>${CLAYTON_LOCATIONS.fuel.name}</strong><small>U91 outlook ${a.forecast?`${money(a.forecast.low)}–${money(a.forecast.high)}/L`:"unavailable for selected date"}</small></span></button></div><div class="distance-strip"><span>Selected trip <strong>${a.tripDistance.toFixed(1)} km</strong></span><span>Single-store baseline <strong>${TRIP_DISTANCE.single.toFixed(1)} km</strong></span><span>Additional distance <strong>${a.extraDistance.toFixed(1)} km</strong></span></div><p class="source-note">Public location names and addresses were checked against retailer or centre listings. Coordinates support this schematic only. Route shapes and distances are illustrative, not live navigation. <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap attribution</a>.</p></section>`;}
function safeMapMarkup(a){try{return mapMarkup(a);}catch(error){console.error("Trip map fallback used",error);return `<section class="trip-card map-card map-fallback"><div class="section-heading"><div><p class="eyebrow">Clayton prototype route map</p><h2>Route-map fallback</h2></div><span class="map-fallback-label">Map fallback ready</span></div><div class="map-fallback-route" role="img" aria-label="Clayton route fallback with starting point, Coles, Woolworths and fuel stop"><div><i class="start-key">S</i><strong>Starting point — Clayton</strong></div><span>→</span><div><i class="coles-key">1</i><strong>${CLAYTON_LOCATIONS.coles.name}</strong></div><span>→</span><div><i class="wool-key">2</i><strong>${CLAYTON_LOCATIONS.woolworths.name}</strong></div><span>→</span><div><i class="fuel-key">3</i><strong>${CLAYTON_LOCATIONS.fuel.name}</strong></div></div><p class="source-note">The map visual could not initialise, so this labelled route remains available. Distances and route order are illustrative.</p></section>`;}}
function fuelAdvisorMarkup(a){const selected=state.trip.shoppingDate;return `<section class="trip-card fuel-advisor"><div class="section-heading"><div><p class="eyebrow">Separate fuel decision module</p><h2>Fuel Timing Advisor</h2></div><span class="fuel-type">U91 only</span></div><div class="fuel-metrics"><div><span>Current illustrative Clayton U91</span><strong>${money(CURRENT_U91)}/L</strong></div><div><span>Recent illustrative range</span><strong>$1.76–$1.92/L</strong></div><div><span>Selected-date range</span><strong>${a.forecast?`${money(a.forecast.low)}–${money(a.forecast.high)}/L`:"Unavailable"}</strong></div><div><span>Forecast midpoint</span><strong>${a.forecast?`${money(a.forecast.mid)}/L`:"—"}</strong></div><div><span>Relative level</span><strong>${a.forecast?.level||"Insufficient Evidence"}</strong></div><div><span>Prototype confidence</span><strong>${a.forecast?.confidence||"Insufficient Evidence"}</strong></div></div><div class="fuel-timeline" aria-label="Seven-day illustrative U91 forecast">${fuelTimeline().map(x=>{const value=dateValue(x.date),chosen=value===selected,low=x.mid<=1.75;return `<div class="fuel-day ${chosen?"selected":""} ${low?"low":""}"><span>${x.date.toLocaleDateString("en-AU",{weekday:"short"})}</span><i style="--fuel-height:${Math.round((x.mid-1.65)*280+24)}px"></i><strong>${money(x.mid)}</strong><small>${money(x.low)}–${money(x.high)}</small>${low?'<b>Best window</b>':""}</div>`;}).join("")}</div><p class="fuel-advice">${a.forecast?(a.forecast.level==="Relatively low"?"Wait and refuel next Tuesday.":"The selected day is not the lowest illustrative window; next Tuesday remains the suggested refuelling day."):"Insufficient Evidence — the selected date is outside the seven-day demonstration forecast. Grocery and route costs still remain available."}</p><div class="forecast-disclosure">Fuel-price forecasts are illustrative and demonstrate how predicted fuel conditions could influence a shopping decision. They are not live PetrolSpy observations or validated model outputs.</div></section>`;}
function calculationMarkup(a){return `<section class="trip-card calculations-card"><div class="section-heading"><div><p class="eyebrow">Transparent calculation</p><h2>From savings to total benefit</h2></div><span>Updates with your settings</span></div><div class="calculation-grid"><article><h3>Additional route cost</h3><dl><div><dt>Extra distance</dt><dd>${a.extraDistance.toFixed(1)} km</dd></div><div><dt>Vehicle efficiency</dt><dd>${state.trip.efficiency.toFixed(1)} L/100km</dd></div><div><dt>Forecast U91 price used</dt><dd>${money(a.fuelPrice)}/L</dd></div><div><dt>Estimated litres consumed</dt><dd>${a.litres.toFixed(2)} L</dd></div><div class="calc-total"><dt>Additional route cost</dt><dd>${money(a.routeCost)}</dd></div></dl><code>${a.extraDistance.toFixed(1)} × ${state.trip.efficiency.toFixed(1)} ÷ 100 × ${a.fuelPrice.toFixed(2)}</code></article><article class="${state.trip.needFuel?"":"calculation-disabled"}"><h3>Refuelling saving</h3>${state.trip.needFuel?`<dl><div><dt>Comparison U91 price</dt><dd>${money(CURRENT_U91)}/L</dd></div><div><dt>Forecast fuel-stop price</dt><dd>${a.forecast?`${money(a.forecast.mid)}/L`:"Unavailable"}</dd></div><div><dt>Expected refill</dt><dd>${state.trip.refillLitres.toFixed(0)} L</dd></div><div class="calc-total"><dt>Gross refuelling saving</dt><dd>${money(a.fuelSaving)}</dd></div></dl>`:"<p>No fuel is required, so refill litres and refuelling saving are excluded.</p>"}</article><article class="benefit-total"><h3>Estimated total benefit</h3><dl><div><dt>Estimated grocery saving</dt><dd>${money(a.grocerySaving)}</dd></div><div><dt>Estimated refuelling saving</dt><dd>${money(a.fuelSaving)}</dd></div><div><dt>Estimated additional route cost</dt><dd>− ${money(a.routeCost)}</dd></div><div class="calc-total"><dt>Estimated total benefit</dt><dd>${money(a.totalBenefit)}</dd></div></dl><code>${money(a.grocerySaving)} + ${money(a.fuelSaving)} − ${money(a.routeCost)}</code></article></div></section>`;}
function tripEmpty(){return `<div class="trip-empty"><img src="./assets/pricepaw-cat.png" alt="Maple, the PromoPaw shopping assistant"/><div><p class="eyebrow">Clayton trip planning</p><h1 id="trip-title">Add products before planning your trip</h1><p>Maple needs a Basket to compare stores, route assumptions and illustrative U91 timing.</p><div><button type="button" data-go-shop>Browse products</button><button type="button" class="secondary" id="load-demo-basket">Load Clayton demo basket</button></div><small>This explicitly adds White Sugar, Butter, two Strawberry packs and Laundry Liquid to Basket.</small></div></div>`;}
function cleanTripCopy(){const label=$(".trip-hero .eyebrow");if(label&&label.textContent.includes("Stage 4"))label.textContent="Clayton · decision-support prototype";}
function renderTrip(){const root=$("#trip-content");if(!state.basket.length){root.innerHTML=tripEmpty();bindGoShop();$("#load-demo-basket").onclick=()=>{if(!confirm("Load the illustrative Clayton demo basket? This will add four catalogue products to your Basket."))return;state.basket=[{productId:"white-sugar",quantity:1,retailer:"coles"},{productId:"butter",quantity:1,retailer:"woolworths"},{productId:"strawberries",quantity:2,retailer:"woolworths"},{productId:"laundry-liquid",quantity:1,retailer:"coles"}];saveState();showToast("Clayton demo basket loaded.");};return;}const a=tripAnalysis(),date=new Date(`${state.trip.shoppingDate}T12:00:00`),isNext=state.trip.shoppingDate===nextTuesday(),weekday=date.toLocaleDateString("en-AU",{weekday:"long"}),heading=a.useSplit?`Recommended plan: Shop ${isNext?"next Tuesday":weekday}${state.trip.needFuel&&a.forecast?" and refuel on the way home":""}`:`Recommended plan: Use ${a.singleRetailer} only${state.trip.needFuel&&a.forecast?" and refuel only if convenient":""}`,plan=a.useSplit?"Selected split-store route":`${a.singleRetailer}-only trip`;root.innerHTML=`<header class="trip-hero"><div><p class="eyebrow">Stage 4 · decision-support prototype</p><h1 id="trip-title">Clayton Smart Trip Planner</h1><p>Clayton is the demonstration area for this prototype. Additional Melbourne areas are planned.</p></div><button type="button" data-go-shop>← Back to Shop</button></header><div class="trip-disclosure">Trip recommendations use illustrative prices, forecasts, distances and vehicle assumptions to demonstrate the proposed decision workflow.</div><section class="trip-settings trip-card"><div><p class="eyebrow">Trip settings</p><h2>Plan one Clayton shop</h2></div><div class="settings-grid"><label>Area<input value="Clayton" disabled/></label><label>Shopping date<span class="date-helper">${isNext?"Next Tuesday · ":""}${eventDateLabel(state.trip.shoppingDate)}</span><input type="date" min="${dateValue(new Date())}" value="${state.trip.shoppingDate}" data-trip-date/></label><label>Fuel type<input value="Unleaded 91 (U91)" disabled/></label><label>Vehicle efficiency<span>L/100km</span><input type="number" min="0.1" max="40" step="0.1" value="${state.trip.efficiency}" data-trip-efficiency/></label><label>Need fuel on this trip<select data-trip-fuel><option value="yes" ${state.trip.needFuel?"selected":""}>Yes</option><option value="no" ${!state.trip.needFuel?"selected":""}>No</option></select></label><label class="${state.trip.needFuel?"":"disabled-setting"}">Expected refill<span>litres</span><input type="number" min="0" max="150" step="1" value="${state.trip.refillLitres}" data-trip-refill ${state.trip.needFuel?"":"disabled"}/></label></div><p class="input-error" id="trip-input-error" aria-live="polite"></p></section><section class="decision-card ${a.useSplit?"positive":"single"}"><p class="eyebrow">Final recommendation</p><h2>${heading}</h2><div class="decision-equation"><details open><summary>${a.useSplit?`The selected split basket is ${money(a.grocerySaving)} below the cheapest single-store basket`:`${a.singleRetailer} is the better single-store option`}</summary><p>${a.useSplit?`Selected allocation: ${money(a.selected)}; cheapest single store: ${money(a.single)}.`:`The potential split saving of ${money(Math.max(0,a.grocerySaving))} does not cover the extra route cost.`}</p></details><span>+</span><details open><summary>${state.trip.needFuel?(a.forecast?`U91 forecast: ${money(a.forecast.low)}–${money(a.forecast.high)}/L`:"Fuel evidence is insufficient"):"No refuelling is required"}</summary><p>${state.trip.needFuel?(a.forecast?`The selected date is ${a.forecast.level.toLowerCase()} with ${a.forecast.confidence.toLowerCase()} prototype confidence.`:"The trip decision uses grocery and route costs only."):"Fuel saving is excluded from the calculation and recommendation."}</p></details><span>−</span><details open><summary>Additional route cost: ${money(a.routeCost)}</summary><p>${a.extraDistance.toFixed(1)} km × ${state.trip.efficiency.toFixed(1)} L/100km × ${money(a.fuelPrice)}/L.</p></details><span>=</span><strong>${plan}${state.trip.needFuel&&a.forecast?" · refuel if following the outlook":" · no fuel stop required"}</strong></div><footer><span>Estimated total benefit</span><b>${money(a.totalBenefit)}</b><small>${a.totalBenefit>0?"Positive illustrative benefit":"No positive illustrative benefit"}</small></footer></section>${safeMapMarkup(a)}<section class="trip-card scenarios-card"><div class="section-heading"><div><p class="eyebrow">Store allocation</p><h2>Three Basket scenarios</h2></div><span>Current quantities and selected retailers</span></div><div class="scenario-grid">${scenarioCard("coles","All products at Coles",a.t.coles,1,`${TRIP_DISTANCE.single.toFixed(1)} km single-store assumption`,a.single-a.t.coles,!a.useSplit&&a.singleRetailer==="Coles")}${scenarioCard("woolworths","All products at Woolworths",a.t.woolworths,1,`${TRIP_DISTANCE.single.toFixed(1)} km single-store assumption`,a.single-a.t.woolworths,!a.useSplit&&a.singleRetailer==="Woolworths")}${scenarioCard("split","Selected split basket",a.selected,a.storeCount,`${a.tripDistance.toFixed(1)} km selected-allocation assumption`,a.grocerySaving,a.useSplit)}</div><p class="comparison-note">Grocery saving is measured against the cheapest single-store basket before travel costs.</p></section>${fuelAdvisorMarkup(a)}${calculationMarkup(a)}<section class="trip-card assumptions-card"><p class="eyebrow">Evidence boundary</p><h2>What is verified and what is illustrative</h2><div><article><h3>Public location details checked</h3><p>Coles Clayton — 2–4 Cooke St; Woolworths Clayton M-City — M02, 2107 Dandenong Rd; EG Ampol Clayton — 190–198 Wellington Rd. Coordinates are used only to position this schematic.</p></article><article><h3>Illustrative prototype inputs</h3><p>Grocery prices, route distances, route cost, U91 history and forecast, fuel saving, total benefit and Maple’s explanation are not live observations or validated model outputs.</p></article></div><button type="button" id="explain-trip">Ask Maple to explain this trip</button></section>`;bindTrip();}
function correctTripDecision(a){const equation=$(".decision-equation"),footer=$(".decision-card footer");if(!equation||!footer)return;const fuelEvidence=state.trip.needFuel?(a.forecast?`Illustrative U91 forecast: ${money(a.forecast.low)}–${money(a.forecast.high)}/L. The selected date is ${a.forecast.level.toLowerCase()} with ${a.forecast.confidence.toLowerCase()} prototype confidence.`:"Fuel evidence is insufficient; no forecast range is used."):"No fuel is required, so refuelling saving is excluded.";equation.innerHTML=`<details open><summary>Estimated grocery saving: ${money(a.grocerySaving)}</summary><p>Selected allocation: ${money(a.selected)}; cheapest single-store baseline: ${money(a.single)}.</p></details><span>+</span><details open><summary>Estimated refuelling saving: ${money(a.fuelSaving)}</summary><p>${fuelEvidence}</p></details><span>−</span><details open><summary>Estimated additional route cost: ${money(a.routeCost)}</summary><p>${a.extraDistance.toFixed(1)} km × ${state.trip.efficiency.toFixed(1)} L/100km × ${money(a.fuelPrice)}/L.</p></details><span>=</span><strong>Estimated total benefit: ${money(a.totalBenefit)}</strong>`;const route=a.useSplit?(state.trip.needFuel&&a.forecast?"Start → 1 Coles Clayton → 2 Woolworths Clayton M-City → 3 EG Ampol Clayton → return journey":"Start → 1 Coles Clayton → 2 Woolworths Clayton M-City → return journey"):`Start → ${a.singleRetailer} → return journey`;footer.innerHTML=`<span>${route}</span><small>${a.totalBenefit>0?"Positive illustrative benefit":"No positive illustrative benefit"}</small>`;}
function bindTrip(){correctTripDecision(tripAnalysis());$$('[data-go-shop]').forEach(b=>b.onclick=()=>showShop(true));const update=(key,value)=>{state.trip[key]=value;saveState();};$$('[data-trip-date]').forEach(x=>x.onchange=()=>{if(!x.value||x.value<dateValue(new Date())){$("#trip-input-error").textContent="Choose today or a future shopping date.";return;}update("shoppingDate",x.value);});$$('[data-trip-efficiency]').forEach(x=>x.onchange=()=>{const n=Number(x.value);if(!Number.isFinite(n)||n<=0){$("#trip-input-error").textContent="Vehicle efficiency must be greater than zero.";x.value=state.trip.efficiency;return;}update("efficiency",n);});$$('[data-trip-fuel]').forEach(x=>x.onchange=()=>update("needFuel",x.value==="yes"));$$('[data-trip-refill]').forEach(x=>x.onchange=()=>{const n=Number(x.value);if(!Number.isFinite(n)||n<0){$("#trip-input-error").textContent="Expected refill amount cannot be negative.";x.value=state.trip.refillLitres;return;}update("refillLitres",n);});$$('[data-map-marker]').forEach(x=>{const show=()=>showMarker(x.dataset.mapMarker);x.onclick=show;x.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();show();}};});$("#explain-trip").onclick=()=>{addMessage("user","Explain this trip");addMessage("maple",tripExplanation());setMobileAssistant(true);};}
function showMarker(id){const l=CLAYTON_LOCATIONS[id],a=tripAnalysis();let extra=l.address;if(id==="coles"||id==="woolworths"){const items=state.basket.filter(x=>x.retailer===id),subtotal=items.reduce((s,x)=>s+products.find(p=>p.slug===x.productId)[id]*x.quantity,0);extra+=` · ${items.length?items.map(x=>products.find(p=>p.slug===x.productId).name).join(", "):"No assigned products"} · ${money(subtotal)}`;}if(id==="fuel")extra+=` · ${a.forecast?`${money(a.forecast.low)}–${money(a.forecast.high)}/L illustrative U91 outlook`:"Fuel outlook unavailable"}`;$("#marker-detail").innerHTML=`<strong>${l.name}</strong><span>${extra}</span>`;}
function tripExplanation(){const a=tripAnalysis(),date=eventDateLabel(state.trip.shoppingDate);if(!a.useSplit)return`For ${date}, the second supermarket stop does not appear worthwhile. The potential grocery saving is ${money(Math.max(0,a.grocerySaving))}, while the additional drive is estimated at ${money(a.routeCost)}. Buying everything from ${a.singleRetailer} may be the better choice. ${state.trip.needFuel&&a.forecast?`The separate illustrative U91 outlook is ${a.forecast.level.toLowerCase()}, but it does not justify an unnecessary store stop.`:"No refuelling conclusion is included."}`;return`For ${date}, your selected split basket is estimated to save ${money(a.grocerySaving)} before travel costs. The additional drive is estimated at ${money(a.routeCost)}. ${state.trip.needFuel&&a.forecast?`Nearby U91 is in a ${a.forecast.level.toLowerCase()} illustrative forecast window, adding an estimated ${money(a.fuelSaving)} gross fuel saving.`:"No fuel saving is included."} Estimated total benefit: ${money(a.totalBenefit)}. This uses illustrative prices, distances and forecasts, not live traffic or petrol data.`;}
function renderTripFailure(error){console.error("Trip Planner render failed",error);$("#trip-content").innerHTML=`<header class="trip-hero"><div><p class="eyebrow">Decision-support prototype</p><h1 id="trip-title">Smart Trip Planner — Clayton</h1><p>Clayton is the demonstration area for this prototype.</p></div><button type="button" data-go-shop>← Back to Shop</button></header><div class="trip-disclosure">The planner could not complete one calculation. Your Basket and saved lists are unchanged.</div>${safeMapMarkup({forecast:null,tripDistance:0,extraDistance:0})}<section class="trip-card"><h2>Trip calculations temporarily unavailable</h2><p>Return to Basket and try again. No saved shopping data has been removed.</p></section>`;bindGoShop();}
function openTrip(update=false){selectedProduct=null;currentView=TRIP_VIEW;hideViews();tripView.hidden=false;setActive(TRIP_VIEW);setMobileContext(null);document.title="Clayton Smart Trip Planner | PromoPaw";if(update)history.pushState({view:TRIP_VIEW},"",`?view=${TRIP_VIEW}`);try{renderTrip();}catch(error){renderTripFailure(error);}window.scrollTo({top:0,behavior:"smooth"});}
function openList(view,update=false){selectedProduct=null;currentView=view;hideViews();(view==="basket"?basketView:watchlistView).hidden=false;setActive(view);setMobileContext(null);document.title=`${view==="basket"?"Basket":"Watchlist"} | PromoPaw`;view==="basket"?renderBasket():renderWatchlist();if(update)history.pushState({view},"",`?view=${view}`);window.scrollTo({top:0,behavior:"smooth"});}
function priceLevel(p){const k=p.cheaper.toLowerCase(),v=p[k],t=p[k==="coles"?"typicalColes":"typicalWoolworths"];return v<=t*.9?"low":v>=t*1.08?"high":"typical";}
function daysUntil(v){const d=new Date(`${v}T12:00:00`),today=new Date();today.setHours(12,0,0,0);return Math.max(0,Math.round((d-today)/86400000));}
function decision(p){const days=daysUntil($("#required-date").value);if(p.rec==="Insufficient Evidence")return{state:p.rec,title:"Evidence is insufficient",copy:`The demonstration history does not support a reliable Buy Now or Wait decision. Compare both current prices and use your ${days}-day deadline as the practical guide.`,days};if(p.rec==="Wait"&&days>4)return{state:"Wait",title:"Wait and watch",copy:`${p.cheaper} is cheaper today, but the illustrative ${days>=14?"14-day":"7-day"} outlook suggests a better promotion may arrive before your required date.`,days};if(p.rec==="Wait")return{state:"Buy Now",title:`Buy Now at ${p.cheaper}`,copy:`Your required date is ${days===0?"today":`only ${days} day${days===1?"":"s"} away`}. Waiting for the modelled promotion window would extend beyond your deadline.`,days};return{state:"Buy Now",title:`Buy Now at ${p.cheaper}`,copy:p.slug==="white-sugar"?"The current Coles price is close to the illustrative historical low. Waiting may not produce a meaningful additional saving before your required date.":`The current better price at ${p.cheaper} is low relative to the illustrative history. Waiting is unlikely to produce a meaningful additional saving before your required date.`,days};}
function updateDecision(p){const d=decision(p),special=p.special?`Yes — ${p.cheaper} has the current illustrative special.`:"No — both retailers show regular illustrative prices.",outlookText=d.days<=4?"The required date is too close to wait for the modelled window.":`${p.outlook7[0]} within 7 days; ${p.outlook14[0]} within 14 days.`;const panel=$("#recommendation-panel");panel.className=`recommendation-panel state-${d.state.toLowerCase().replaceAll(" ","-")}`;panel.innerHTML=`<div class="recommendation-label"><span>PromoPaw recommendation</span><b>${d.state}</b></div><h2 id="recommendation-title">${d.title}</h2><p>${d.copy}</p><dl><div><dt>On special now?</dt><dd>${special}</dd></div><div><dt>Better current price</dt><dd>${p.cheaper} at ${money(p[p.cheaper.toLowerCase()])}.</dd></div><div><dt>Current price level</dt><dd>${priceLevel(p).replace(/^./,c=>c.toUpperCase())} relative to illustrative history.</dd></div><div><dt>Better promotion likely?</dt><dd>${outlookText}</dd></div></dl>`;$("#action-area").innerHTML=`<div><h2>Ready for your next step?</h2><p>Items are saved on this device. A qualifying Wait decision earns 10 coins once.</p></div><div class="action-buttons"><button type="button" data-action="basket" class="${d.state==="Buy Now"?"recommended":""}">Add to Basket</button><button type="button" data-action="watchlist" class="${d.state==="Wait"?"recommended":""}">Add to Watchlist</button></div>`;$("[data-action='basket']").onclick=()=>addBasket(p);$("[data-action='watchlist']").onclick=()=>openWatchDialog(p,$("#required-date").value);}
function mapleNote(p){if(p.slug==="white-sugar")return"Sugar is currently cheaper at Coles and already close to its illustrative historical low.";if(p.rec==="Wait")return`${p.name} is cheaper at ${p.cheaper}, but the illustrative outlook suggests another promotion may be worth waiting for.`;if(p.rec==="Insufficient Evidence")return`${p.name} does not yet have enough consistent demonstration history for a confident timing recommendation.`;return`${p.name} is currently cheaper at ${p.cheaper} and looks low against its illustrative price history.`;}
function renderAnalysis(p){const status=p.special?`${p.cheaper} is currently marked On Special in this demonstration.`:"Neither retailer is marked On Special in this demonstration.";$("#promotion-card").innerHTML=`<div><p class="eyebrow">Current promotion analysis</p><h2>${status}</h2></div><p>${p.cheaper} offers the better current price at <strong>${money(p[p.cheaper.toLowerCase()])}</strong>. This is <strong>${priceLevel(p)}</strong> relative to the product’s illustrative history.</p>`;$("#outlook-grid").innerHTML=outlook(7,p.outlook7)+outlook(14,p.outlook14);}
function addMessage(role,text,persist=true){state.assistant.conversation.push(role==="maple"?mapleMessage(text):{role,text});state.assistant.conversation=state.assistant.conversation.slice(-30);if(persist)saveState();}
function mapleVoice(text,voice){const value=String(text||"").trim();if(!value)return value;return voice==="end"?`${value} Meow meow.`:`Meow — ${value}`;}
function productFromText(text){const q=text.toLowerCase();return products.find(p=>q.includes(p.name.toLowerCase())||q.includes(p.slug.split("-")[0]))||(q.includes("sugar")?products[0]:null)||(q.includes("flour")?products[1]:null)||(q.includes("cream")?products[3]:null)||(q.includes("milk")?products[5]:null);}
function planGroups(){const chosen=(state.assistant.plan?.ingredients||[]).filter(x=>x.included).map(x=>({...x,product:products.find(p=>p.slug===x.productId)}));return{good:chosen.filter(x=>x.product.stability==="Shelf-stable"&&x.product.rec==="Buy Now"),watch:chosen.filter(x=>x.product.stability==="Shelf-stable"&&x.product.rec==="Wait"),later:chosen.filter(x=>x.product.stability==="Perishable"||x.product.rec==="Insufficient Evidence")};}
function eventDateLabel(value){return new Date(`${value}T12:00:00`).toLocaleDateString("en-AU",{day:"numeric",month:"long",year:"numeric"});}
function planProductRow(item,mode="edit"){const p=products.find(x=>x.slug===item.productId);if(mode==="edit")return `<div class="ingredient-row"><label><input type="checkbox" data-ingredient-check="${p.slug}" ${item.included?"checked":""}/><span class="ingredient-checkmark">✓</span>${productThumb(p,"ingredient-thumb")}<span class="ingredient-name"><strong>${p.name}</strong><small>${p.size} · ${p.stability}</small></span></label><div class="plan-quantity"><button type="button" data-plan-qty="-1" data-id="${p.slug}" aria-label="Decrease ${p.name} quantity">−</button><b>${item.quantity}</b><button type="button" data-plan-qty="1" data-id="${p.slug}" aria-label="Increase ${p.name} quantity">+</button></div></div>`;return `<label class="plan-action-row"><input type="checkbox" data-plan-select="${p.slug}" data-plan-group="${mode}" checked/><span><strong>${p.name}</strong><small>${p.size} · Qty ${item.quantity}</small></span></label>`;}
function maplePlanMarkup(){const plan=state.assistant.plan;if(!plan)return"";if(plan.stage==="event")return `<section class="guided-step"><div class="step-kicker">Birthday cake plan · Step 1 of 4</div><h3>Confirm the event</h3><p>“Next month” is not an exact date. Choose the birthday date before Maple makes a plan.</p><form data-event-form><label>Event type<input value="Birthday" disabled/></label><label>Event date<input type="date" data-event-date min="${dateValue(futureDate(1))}" value="${plan.eventDate||""}" required/></label><label>Number of people<input type="number" data-event-people min="1" max="30" value="${plan.people}" required/></label><button type="submit">Continue to ingredients</button><span class="maple-error" data-plan-error></span></form></section>`;if(plan.stage==="ingredients")return `<section class="guided-step"><div class="step-kicker">Birthday cake plan · Step 2 of 4</div><h3>Confirm the ingredients</h3><p class="plan-warning">Suggested ingredients must be confirmed before they are added to your plan.</p><div class="ingredient-list">${plan.ingredients.map(x=>planProductRow(x)).join("")}</div><button type="button" class="plan-primary" data-confirm-ingredients>Confirm ingredient list</button><span class="maple-error" data-plan-error></span></section>`;const g=planGroups(),buyDate=new Date(`${plan.eventDate}T12:00:00`);buyDate.setDate(buyDate.getDate()-2);const closer=eventDateLabel(dateValue(buyDate<new Date()?new Date():buyDate));const group=(title,kind,items,copy)=>`<div class="plan-group ${kind}"><header><h4>${title}</h4><span>${items.length}</span></header><p>${copy}</p>${items.length?items.map(x=>planProductRow(x,kind)).join(""):'<small>No selected products in this group.</small>'}</div>`;return `<section class="guided-step plan-ready"><div class="step-kicker">Birthday cake plan · Steps 3–4</div><h3>Shopping plan for ${eventDateLabel(plan.eventDate)}</h3><p>For ${plan.people} people. Nothing is added until you choose an action below.</p>${group("Good value now","good",g.good,"Shelf-stable products with a Buy Now recommendation.")}${group("Watch for a promotion","watch",g.watch,"There is time to wait, and all recommendations remain before the event.")}${group("Buy closer to the event","later",g.later,`Perishable products should normally be bought by ${closer}. This is a visible plan, not a reminder.`)}<div class="plan-actions"><button type="button" data-plan-add="basket" ${g.good.length?"":"disabled"}>Add selected buy-now items to Basket</button><button type="button" data-plan-add="watchlist" ${g.watch.length?"":"disabled"}>Add selected watch items to Watchlist</button></div></section>`;}
function mapleMarkup(surface){const a=state.assistant,drawer=surface==="drawer",context=selectedProduct?`Ask about ${selectedProduct.name}`:currentView===TRIP_VIEW?"Clayton trip context":"Shopping assistant";const messages=a.conversation.map(m=>`<div class="maple-message ${m.role}"><span>${m.role==="maple"?"Maple":"You"}</span><p>${esc(m.role==="maple"?mapleVoice(m.text,m.voice):m.text)}</p></div>`).join("");const productChip=selectedProduct?`<button type="button" data-maple-prompt="Should I wait for ${selectedProduct.name}?">Should I wait?</button>`:"",tripChip=currentView===TRIP_VIEW?'<button type="button" data-maple-prompt="Explain this trip">Explain this trip</button>':"";return `${drawer?'<div class="mobile-assistant-handle"></div><button class="mobile-assistant-close" type="button" data-maple-close aria-label="Close Maple">×</button>':""}<div class="maple-top"><div class="maple-identity mood-${a.mood.toLowerCase()}"><img src="./assets/pricepaw-cat.png" alt="Maple, the PromoPaw shopping assistant"/><div><span>Scripted prototype assistant</span><h2>Maple</h2><p><i aria-hidden="true"></i>Mood: <strong>${a.mood}</strong></p></div></div><button type="button" class="reset-demo" data-reset-demo title="Reset conversation, lists, rewards, trip settings and mood">Reset demo</button></div><div class="maple-balance"><span><i aria-hidden="true">●</i><b>${a.coins}</b> coins</span><button type="button" data-treat ${a.coins<50?"aria-disabled=\"true\"":""}>Give Maple a treat — 50 coins</button></div><p class="maple-context-label">${context}</p><div class="maple-conversation" role="log" aria-live="polite">${messages}</div>${maplePlanMarkup()}<div class="maple-chips" aria-label="Maple suggestions"><button type="button" data-maple-prompt="Find breakfast basics.">Find breakfast basics</button><button type="button" data-maple-prompt="What’s on special?">What’s on special?</button><button type="button" data-maple-prompt="Show me the cheaper options.">Cheaper options</button>${productChip}${tripChip}<button type="button" data-maple-prompt="Help me plan for a birthday.">Plan a birthday cake</button></div><form class="maple-form" data-maple-form><label>Message Maple</label><div><input data-maple-input placeholder="Ask about a product, plan or trip" autocomplete="off"/><button type="submit" aria-label="Send message"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="m5 12 14-7-4 14-3-5-7-2Zm7 2 7-9"/></svg></button></div></form><p class="maple-disclosure">Maple is a scripted prototype assistant using illustrative catalogue and forecast data.</p>`;}
function renderMaple(){const desktop=$("#desktop-maple");if(desktop)desktop.innerHTML=mapleMarkup("desktop");if(mobilePanel)mobilePanel.innerHTML=mapleMarkup("drawer");bindMaple();requestAnimationFrame(()=>$$('.maple-conversation').forEach(x=>x.scrollTop=x.scrollHeight));}
function startBirthday(){state.assistant.plan={stage:"event",eventDate:null,people:8,ingredients:cakeIds.map(productId=>({productId,included:true,quantity:1}))};return"Lovely — let’s plan the strawberry cream cake. First, confirm the birthday date and number of people. I won’t treat “next month” as an exact date.";}
function scriptedResponse(text){const q=text.toLowerCase();if(q.includes("explain this trip")&&currentView===TRIP_VIEW)return tripExplanation();if(q.includes("birthday")||q.includes("strawberry cream cake"))return startBirthday();if(q.includes("breakfast")){const list=products.filter(p=>p.extraCategories?.includes("Breakfast")).map(p=>`${p.name} ${p.size} — ${money(p[p.cheaper.toLowerCase()])} at ${p.cheaper}`).join("\n");return`Breakfast basics in this demonstration catalogue:\n${list}`;}if(q.includes("special")){const list=products.filter(p=>p.special).map(p=>`${p.name} ${p.size} — ${money(p[p.cheaper.toLowerCase()])} at ${p.cheaper}`).join("\n");return`These demonstration products are marked On Special:\n${list}\nThese are illustrative prices, not live retailer observations.`;}if(q.includes("cheaper")||q.includes("compare")){return`Current cheaper options in the demonstration catalogue:\n${products.map(p=>`${p.name}: ${p.cheaper} at ${money(p[p.cheaper.toLowerCase()])}`).join("\n")}`;}if(q.includes("wait")){const p=productFromText(text)||selectedProduct;if(!p)return"Tell me which demonstration product you mean, and I’ll check its current recommendation.";if(p.slug==="white-sugar")return`White Sugar 1kg is a Buy Now item. Coles is currently cheaper at ${money(p.coles)}, close to its illustrative historical low.`;return`${p.name} ${p.size} currently has a ${p.rec} recommendation. ${p.cheaper} is cheaper at ${money(p[p.cheaper.toLowerCase()])}. ${reasonFor(p)}`;}return"I can currently help you compare the demonstration products, review promotion outlooks, manage your Watchlist, plan the strawberry-cream-cake scenario, or explain the current Clayton trip.";}
function sendMaple(text){const value=text.trim();if(!value)return;state.assistant.conversation.push({role:"user",text:value});state.assistant.mood="Thinking";saveState();setTimeout(()=>{state.assistant.conversation.push(mapleMessage(scriptedResponse(value)));if(state.assistant.mood==="Thinking")state.assistant.mood="Curious";saveState();},380);}
function addPlanItems(kind,root){const plan=state.assistant.plan,selected=[...root.querySelectorAll(`[data-plan-select][data-plan-group="${kind}"]:checked`)].map(x=>x.dataset.planSelect);if(!selected.length){showToast("Choose at least one planned item first.");return;}let added=0,rewards=0;for(const id of selected){const p=products.find(x=>x.slug===id),ingredient=plan.ingredients.find(x=>x.productId===id);if(kind==="good"){if(state.watchlist.some(x=>x.productId===id)&&!confirm(`${p.name} is in Watchlist. Move it to Basket?`))continue;state.watchlist=state.watchlist.filter(x=>x.productId!==id);if(!state.basket.some(x=>x.productId===id)){state.basket.push({productId:id,quantity:ingredient.quantity,retailer:p.cheaper.toLowerCase()});added++;}}else{if(state.basket.some(x=>x.productId===id)&&!confirm(`${p.name} is in Basket. Move it to Watchlist?`))continue;state.basket=state.basket.filter(x=>x.productId!==id);if(!state.watchlist.some(x=>x.productId===id)){state.watchlist.push({productId:id,requiredBy:plan.eventDate,targetPrice:null});added++;if(maybeReward(p,plan.eventDate))rewards++;}}}saveState();showToast(`${added} ${added===1?"item":"items"} added${rewards?` · +${rewards*10} coins for thoughtful waiting`:""}.`);}
function bindMaple(){
  $$('[data-maple-form]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const input=f.querySelector('[data-maple-input]');sendMaple(input.value);});$$('[data-maple-prompt]').forEach(b=>b.onclick=()=>sendMaple(b.dataset.maplePrompt));$$('[data-maple-close]').forEach(b=>b.onclick=()=>setMobileAssistant(false));
  $$('[data-treat]').forEach(b=>b.onclick=()=>{if(state.assistant.coins<50){const need=50-state.assistant.coins;addMessage("maple",`I need ${need} more coin${need===1?"":"s"} before my next treat.`);return;}state.assistant.coins-=50;state.assistant.mood="Delighted";addMessage("maple","Maple loved the treat! Thoughtful saving makes her happy.");});
  $$('[data-reset-demo]').forEach(b=>b.onclick=()=>{if(!confirm("Reset Maple’s conversation, birthday plan, Basket, Watchlist, trip settings, coins, reward history and mood? This cannot be undone."))return;state={basket:[],watchlist:[],assistant:cleanAssistant(),trip:cleanTrip()};saveState();showToast("PromoPaw’s clean demonstration state has been restored.");});
  $$('[data-event-form]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const date=f.querySelector('[data-event-date]').value,people=Number(f.querySelector('[data-event-people]').value),error=f.querySelector('[data-plan-error]');if(!date||date<=dateValue(new Date())){error.textContent="Choose a future birthday date.";return;}state.assistant.plan.eventDate=date;state.assistant.plan.people=Math.max(1,Math.min(30,Math.floor(people)||8));state.assistant.plan.stage="ingredients";saveState();});
  $$('[data-ingredient-check]').forEach(x=>x.onchange=()=>{state.assistant.plan.ingredients.find(i=>i.productId===x.dataset.ingredientCheck).included=x.checked;saveState();});$$('[data-plan-qty]').forEach(b=>b.onclick=()=>{const item=state.assistant.plan.ingredients.find(i=>i.productId===b.dataset.id);item.quantity=Math.max(1,Math.min(6,item.quantity+Number(b.dataset.planQty)));saveState();});$$('[data-confirm-ingredients]').forEach(b=>b.onclick=()=>{if(!state.assistant.plan.ingredients.some(i=>i.included)){$$('[data-plan-error]').forEach(x=>x.textContent="Keep at least one ingredient in the plan.");return;}state.assistant.plan.stage="ready";addMessage("maple","Your ingredient list is confirmed. Review the timing groups, then choose exactly what to add.");});$$('[data-plan-add]').forEach(b=>b.onclick=()=>addPlanItems(b.dataset.planAdd==="basket"?"good":"watch",b.closest('.assistant-panel,.mobile-assistant')));
}
function setMobileContext(){renderMaple();}
function openProduct(slug,update=false){const p=products.find(x=>x.slug===slug);if(!p){showShop(update);return;}selectedProduct=p;currentView="product";selectedRange=8;hideViews();detailView.hidden=false;setActive("product");document.title=`${p.name} ${p.size} | PromoPaw`;$("#breadcrumbs").innerHTML=`<button type="button" id="back-to-shop">Shop</button><span aria-hidden="true">›</span><button type="button" id="category-back">${p.category}</button><span aria-hidden="true">›</span><strong>${p.name}</strong>`;$("#back-to-shop").onclick=()=>showShop(true);$("#category-back").onclick=()=>{showShop(true);const b=categoryButtons.find(x=>x.dataset.category===p.category);if(b)b.click();};renderSummary(p);renderAnalysis(p);renderChart(p);updateDecision(p);$("#maple-product-note").textContent=mapleNote(p);setMobileContext(p);$$('[data-range]').forEach(b=>{b.setAttribute("aria-pressed",String(+b.dataset.range===selectedRange));b.onclick=()=>{selectedRange=+b.dataset.range;$$('[data-range]').forEach(x=>x.setAttribute("aria-pressed",String(x===b)));renderChart(p);};});if(update)history.pushState({product:slug},"",`?product=${slug}`);window.scrollTo({top:0,behavior:"smooth"});}
function showToast(msg){toast.textContent=msg;toast.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove("show"),3000);}
function setMobileAssistant(open){if(open)renderMaple();mobilePanel.hidden=!open;backdrop.hidden=!open;mobileButton.setAttribute("aria-expanded",String(open));document.body.classList.toggle("panel-open",open);const target=open?mobilePanel.querySelector('[data-maple-close]'):mobileButton;if(target)target.focus();}

function syncTripSurface(){cleanTripCopy();if(currentView!==TRIP_VIEW)return;const includeFuel=Boolean(state.trip?.needFuel&&forecastForDate(state.trip.shoppingDate)),routeText=includeFuel?"Start → 1 Coles Clayton → 2 Woolworths Clayton M-City → 3 EG Ampol Clayton → return journey":"Start → 1 Coles Clayton → 2 Woolworths Clayton M-City → return journey";const fuelNodes=[...$$('[data-map-marker="fuel"]'),$(".fuel-route"),$(".map-legend .fuel-key")?.closest("span")],routeNote=$(".route-order-note"),mapSvg=$(".prototype-map svg");fuelNodes.filter(Boolean).forEach(node=>node.toggleAttribute("hidden",!includeFuel));if(routeNote&&routeNote.textContent.trim()!==`Route order: ${routeText}`)routeNote.innerHTML=`<strong>Route order:</strong> ${routeText}`;if(mapSvg)mapSvg.setAttribute("aria-label",includeFuel?"Schematic Clayton route: Start, then Coles, Woolworths and fuel stop":"Schematic Clayton route: Start, then Coles and Woolworths, returning without a fuel stop");}
new MutationObserver(syncTripSurface).observe($("#trip-content"),{childList:true,subtree:true});

search.oninput=()=>{if(currentView!=="shop")showShop(false);renderProducts();};document.addEventListener("keydown",e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();search.focus();}if(e.key==="Escape"&&!mobilePanel.hidden)setMobileAssistant(false);});categoryButtons.forEach(b=>b.onclick=()=>{selectedCategory=b.dataset.category;categoryButtons.forEach(x=>{const on=x===b;x.classList.toggle("active",on);x.setAttribute("aria-pressed",String(on));});renderProducts();});$("#clear-search").onclick=()=>{search.value="";selectedCategory="All";categoryButtons.forEach(x=>{const on=x.dataset.category==="All";x.classList.toggle("active",on);x.setAttribute("aria-pressed",String(on));});renderProducts();search.focus();};$(".wordmark").onclick=e=>{e.preventDefault();showShop(true);};$(".nav-links a").onclick=e=>{e.preventDefault();showShop(true);};$$('[data-view]').forEach(b=>b.onclick=()=>b.dataset.view===TRIP_VIEW?openTrip(true):openList(b.dataset.view,true));bindGoShop();mobileButton.onclick=()=>setMobileAssistant(true);backdrop.onclick=()=>setMobileAssistant(false);$("#maple-context-button").onclick=()=>setMobileAssistant(true);$$('[data-deferred]').forEach(b=>b.onclick=()=>showToast("This feature is planned for a later stage."));
$("#watch-dialog-form").onsubmit=e=>{e.preventDefault();if(!pendingWatch)return;const required=$("#watch-required-date").value,targetRaw=$("#watch-target-price").value,target=targetRaw===""?null:Number(targetRaw);if(!required||required<dateValue(new Date())){$("#watch-dialog-error").textContent="Choose today or a future required-by date.";return;}if(target!==null&&(!Number.isFinite(target)||target<0)){$("#watch-dialog-error").textContent="Target price must be zero or more.";return;}const p=pendingWatch.product;state.watchlist=state.watchlist.filter(x=>x.productId!==p.slug);if(pendingWatch.fromBasket)state.basket=state.basket.filter(x=>x.productId!==p.slug);state.watchlist.push({productId:p.slug,requiredBy:required,targetPrice:target});const rewarded=maybeReward(p,required);$("#watch-dialog").close();pendingWatch=null;saveState();showToast(`${p.name} was added to Watchlist.${rewarded?" +10 coins — thoughtful waiting!":""}`);};
$$('[data-close-dialog]').forEach(b=>b.onclick=()=>$("#watch-dialog").close());$("#watch-dialog").addEventListener("close",()=>{pendingWatch=null;});window.addEventListener("storage",e=>{if(e.key===STORAGE_KEY){state=loadState();updateCounters();renderMaple();if(currentView==="basket")renderBasket();if(currentView==="watchlist")renderWatchlist();if(currentView===TRIP_VIEW)renderTrip();}});window.onpopstate=()=>{const params=new URLSearchParams(location.search),slug=params.get("product"),view=params.get("view");slug?openProduct(slug,false):view===TRIP_VIEW?openTrip(false):["basket","watchlist"].includes(view)?openList(view,false):showShop(false);};
renderProducts();updateCounters();renderMaple();const initialParams=new URLSearchParams(location.search),initialSlug=initialParams.get("product"),initialView=initialParams.get("view");if(initialSlug)openProduct(initialSlug,false);else if(initialView===TRIP_VIEW)openTrip(false);else if(["basket","watchlist"].includes(initialView))openList(initialView,false);else setActive("shop");
